source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    uniform_rows = [(r, row[0]) for r, row in enumerate(grid) if len(set(row)) == 1]
    uniform_cols = [(c, grid[0][c]) for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    # The divider color is the least common color among full uniform lines;
    # uniform background rows/columns are not dividers.
    line_counts = {}
    for _, color in uniform_rows + uniform_cols:
        line_counts[color] = line_counts.get(color, 0) + 1
    if not line_counts:
        return [list(row) for row in grid]
    divider_color = min(line_counts, key=line_counts.get)
    row_cuts = [r for r, color in uniform_rows if color == divider_color]
    col_cuts = [c for c, color in uniform_cols if color == divider_color]
    def intervals(n, cuts):
        spans = []
        start = 0
        for c in sorted(cuts):
            if start < c:
                spans.append((start, c))
            start = c + 1
        if start < n:
            spans.append((start, n))
        return spans
    rows, cols = intervals(h, row_cuts), intervals(w, col_cuts)
    if not rows or not cols:
        return [list(row) for row in grid]
    r0, r1 = rows[0]
    c0, c1 = cols[0]
    tile = [list(row[c0:c1]) for row in grid[r0:r1]]
    out = [list(row) for row in grid]
    for rs, re in rows:
        for cs, ce in cols:
            if re-rs != len(tile) or ce-cs != len(tile[0]):
                continue
            for i in range(len(tile)):
                out[rs+i][cs:ce] = tile[i][:]
    return out
